"use client";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { auth, db } from "@/lib/firebase";
import { signInWithEmailAndPassword, GoogleAuthProvider, signInWithPopup } from "firebase/auth";
import Link from "next/link";
import { setDoc, doc } from "firebase/firestore";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const router = useRouter();
  const handleLogin = async (e) => {
  e.preventDefault();

  try {
    await signInWithEmailAndPassword(auth, email, password);

    router.replace("/");
    router.refresh();
  } catch (error) {
    alert("Sai email hoặc mật khẩu!");
  }
  };
const handleGoogleSignIn = async () => {
  try {
    const provider = new GoogleAuthProvider();
    await signInWithPopup(auth, provider);

    router.replace("/");
    router.refresh();
  } catch (error) {
    alert(error.message);
  }
  }; 
  return (
    <div className="text-black">
    <div style={{ paddingTop: "100px", display: "flex", justifyContent: "center", alignItems: "center", width: "100%", height: "100vh", background: "#F7F7F8" }}>
      
      <div style={{ width: "540px", padding: "40px", background: "white", borderRadius: "10px", display: "flex", flexDirection: "column", gap: "40px" }}>

        <div style={{ textAlign: "center" }}>
          <h1 style={{ fontSize: "38px", fontWeight: 600, color: "#000000" }}>Đăng nhập</h1>
          <p style={{color: "#000000"}}>Chào mừng quay lại! Vui lòng đăng nhập để truy cập tài khoản của bạn.</p>
        </div>

        <form onSubmit={handleLogin} style={{ display: "flex", flexDirection: "column", gap: "20px" }}>

          <input
            color="#000000"
            type="email"
            placeholder="Nhập email của bạn"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={{ padding: "20px", borderRadius: "8px", border: "1px solid #000000" }}
          />

          <input
            color="#000000"
            type="password"
            placeholder="Nhập mật khẩu của bạn"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{ padding: "20px", borderRadius: "8px", border: "1px solid #000000" }}
          />

          <button
            color="#000000"
            type="button"
            onClick={handleLogin}
            style={{ padding: "14px", background: "black", color: "white", borderRadius: "8px", border: "none", cursor: "pointer" }}
          >
            Đăng nhập
          </button>
          <button
            type="button"
            onClick={handleGoogleSignIn}
            style={{padding: "14px",background: "white",color: "black",borderRadius: "8px",border: "1px solid black",cursor: "pointer"}}> Sign In with Google</button>

        </form>

        <div style={{ textAlign: "center" }}>
          Bạn không có tài khoản?{" "}
          <Link href="/signup" style={{ color: "#000000" }}>Đăng ký</Link>
        </div>

      </div>
    </div>
    </div>
  );
}